    public class TranslationLanguage {
        public string Id,Name,NativeName;public bool RightToLeft;
        public override string ToString(){return Name;}
        public string ShortName{get{return Id=="zh-Hans"?"Chinese (S)":Id=="zh-Hant"?"Chinese (T)":Id=="pt-BR"?"Portuguese BR":Id=="pt-PT"?"Portuguese PT":Name;}}
    }
    public static class TranslationCatalog {
        public static readonly List<TranslationLanguage> All=Build();
        static List<TranslationLanguage> Build(){var map=new Dictionary<string,TranslationLanguage>(StringComparer.OrdinalIgnoreCase);foreach(var culture in CultureInfo.GetCultures(CultureTypes.NeutralCultures).Concat(new[]{CultureInfo.GetCultureInfo("pt-BR"),CultureInfo.GetCultureInfo("pt-PT")})){
            if(String.IsNullOrEmpty(culture.Name)||culture.Name=="zh"||culture.Name.IndexOf("CHS",StringComparison.OrdinalIgnoreCase)>=0||culture.Name.IndexOf("CHT",StringComparison.OrdinalIgnoreCase)>=0)continue;
            map[culture.Name]=new TranslationLanguage{Id=culture.Name,Name=culture.EnglishName,NativeName=culture.NativeName,RightToLeft=culture.TextInfo.IsRightToLeft};
        }
        map["zh-Hans"]=new TranslationLanguage{Id="zh-Hans",Name="Chinese (Simplified)",NativeName="简体中文"};map["zh-Hant"]=new TranslationLanguage{Id="zh-Hant",Name="Chinese (Traditional)",NativeName="繁體中文"};
        map["pt-BR"].Name="Portuguese (Brazil)";map["pt-PT"].Name="Portuguese (Portugal)";return map.Values.OrderBy(v=>v.Name,StringComparer.OrdinalIgnoreCase).ToList();}
        public static TranslationLanguage Find(string value){return All.FirstOrDefault(v=>String.Equals(v.Id,value,StringComparison.OrdinalIgnoreCase)||String.Equals(v.Name,value,StringComparison.OrdinalIgnoreCase));}
        public static IEnumerable<TranslationLanguage> Search(string text){return All.Where(v=>String.IsNullOrWhiteSpace(text)||(v.Name+" "+v.Id+" "+v.NativeName).IndexOf(text.Trim(),StringComparison.OrdinalIgnoreCase)>=0);}
    }
    public class LanguagePreferences {
        public string OcrTag="oneocr-auto",WindowsOcrTag="system",DefaultTarget="el";public List<string> Favorites=new List<string>{"el","en","de"};
        public static LanguagePreferences Load(){try{var raw=File.ReadAllText(Path.Combine(AppStorage.SettingsDirectory,"languages.json"));var serializer=new JavaScriptSerializer();var settings=serializer.Deserialize<LanguagePreferences>(raw);var fields=serializer.Deserialize<System.Collections.Generic.Dictionary<string,object>>(raw);if(settings!=null&&!fields.ContainsKey("WindowsOcrTag")){settings.WindowsOcrTag=settings.OcrTag==OneOcrService.Automatic?"system":settings.OcrTag;if(settings.OcrTag=="system"||settings.OcrTag=="greek-english")settings.OcrTag=OneOcrService.Automatic;}if(settings!=null){if(TranslationCatalog.Find(settings.DefaultTarget)==null)settings.DefaultTarget="el";settings.Favorites=(settings.Favorites??new List<string>{"el","en","de"}).Where(id=>TranslationCatalog.Find(id)!=null).Distinct(StringComparer.OrdinalIgnoreCase).Take(3).ToList();if(String.IsNullOrEmpty(settings.OcrTag))settings.OcrTag="system";return settings;}}catch{}return new LanguagePreferences();}
        public void Save(){string path=Path.Combine(AppStorage.SettingsDirectory,"languages.json"),temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,new JavaScriptSerializer().Serialize(this));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
    }
