    public static class OcrLanguageService {
        public static readonly string[] PackTags={"ar-SA","bg-BG","ca-ES","cs-CZ","da-DK","de-DE","el-GR","en-US","en-GB","es-ES","fi-FI","fr-FR","he-IL","hr-HR","hu-HU","it-IT","ja-JP","ko-KR","nb-NO","nl-NL","pl-PL","pt-BR","pt-PT","ro-RO","ru-RU","sk-SK","sl-SI","sr-Cyrl-RS","sr-Latn-RS","sv-SE","tr-TR","uk-UA","zh-CN","zh-TW"};
        static List<InstalledOcrLanguage> cached;
        public static string CapabilityTag(string tag){if(tag.StartsWith("zh",StringComparison.OrdinalIgnoreCase))return tag.IndexOf("Hant",StringComparison.OrdinalIgnoreCase)>=0||tag.IndexOf("TW",StringComparison.OrdinalIgnoreCase)>=0?"zh-TW":"zh-CN";if(PackTags.Contains(tag,StringComparer.OrdinalIgnoreCase))return PackTags.First(t=>t.Equals(tag,StringComparison.OrdinalIgnoreCase));return PackTags.FirstOrDefault(t=>t.StartsWith(tag+"-",StringComparison.OrdinalIgnoreCase))??tag;}
        public static string Name(string tag){try{return tag=="zh-CN"?"Chinese (Simplified)":tag=="zh-TW"?"Chinese (Traditional)":CultureInfo.GetCultureInfo(tag).EnglishName;}catch{return tag;}}
        public static void Invalidate(){cached=null;}
        public static async Task<List<InstalledOcrLanguage>> Installed(CancellationToken token){if(cached!=null)return cached;var script=Path.Combine(Backend.Base,"ocr-languages.ps1");if(!File.Exists(script))throw new IOException("Keep ocr-languages.ps1 beside ScreenText.exe.");var output=await Backend.Run(PowerShell(),"-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "+Backend.Quote(script)+" -Action List",null,Backend.Base,token,25);var items=new JavaScriptSerializer().Deserialize<List<InstalledOcrLanguage>>(output)??new List<InstalledOcrLanguage>();cached=items.Where(v=>!String.IsNullOrWhiteSpace(v.Tag)).GroupBy(v=>v.Tag,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList();return cached;}
        public static string PowerShell(){return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe");}
        public static ProcessStartInfo InstallCommand(string tag){if(!PackTags.Contains(tag,StringComparer.Ordinal))throw new ArgumentException("Choose a known OCR language pack.");var script=Path.Combine(Backend.Base,"ocr-languages.ps1");if(!File.Exists(script))throw new FileNotFoundException("OCR language helper is missing.");return new ProcessStartInfo(PowerShell(),"-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "+Backend.Quote(script)+" -Action Install -LanguageTag "+Backend.Quote(tag)){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden};}
    }
