            }
        }
        void FilterTargetRows(){if(targetList==null)return;string id=(targetList.SelectedItem as TranslationLanguage)==null?languageSettings.DefaultTarget:((TranslationLanguage)targetList.SelectedItem).Id;targetList.BeginUpdate();targetList.Items.Clear();foreach(var item in TranslationCatalog.Search(targetSearch.Text))targetList.Items.Add(item);targetList.EndUpdate();if(targetList.Items.Count>0){int index=targetList.Items.Cast<TranslationLanguage>().ToList().FindIndex(v=>v.Id==id);targetList.SelectedIndex=Math.Max(0,index);}UpdateTargetActions();}
        void UpdateTargetActions(){if(languageFavorite==null)return;var item=targetList.SelectedItem as TranslationLanguage;languageDefault.Enabled=item!=null&&!busy;languageFavorite.Enabled=item!=null&&!busy;languageFavorite.Text=item!=null&&languageSettings.Favorites.Contains(item.Id)?"Remove favorite":"Add favorite";targetStatus.Text="Default: "+TranslationCatalog.Find(languageSettings.DefaultTarget).Name+"\nFavorites ("+languageSettings.Favorites.Count+"/3): "+String.Join(" · ",languageSettings.Favorites.Select(id=>TranslationCatalog.Find(id).Name));targetList.Invalidate();}
        void SetDefaultTarget(){var item=targetList.SelectedItem as TranslationLanguage;if(item==null||busy)return;languageSettings.DefaultTarget=item.Id;if(result.Text.Length==0)currentTarget=item.Id;SaveLanguagePreferences();RebuildQuickLanguages();UpdateTargetActions();}
        void ToggleTargetFavorite(){var item=targetList.SelectedItem as TranslationLanguage;if(item==null||busy)return;ChangeFavorite(item,settingsWindow);}
        void ChangeFavorite(TranslationLanguage item,IWin32Window owner){if(busy)return;if(languageSettings.Favorites.Contains(item.Id))languageSettings.Favorites.Remove(item.Id);else if(languageSettings.Favorites.Count<3)languageSettings.Favorites.Add(item.Id);else{
            string replace=null;using(var dialog=new Form{Text="Replace favorite",ClientSize=new Size(400,245),StartPosition=FormStartPosition.CenterParent,ShowInTaskbar=false,MinimizeBox=false,MaximizeBox=false,Icon=Icon,Font=Font}){var stack=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(20)};dialog.Controls.Add(stack);stack.Controls.Add(new Label{Text="Replace a favorite with "+item.Name+":",AutoSize=true,MaximumSize=new Size(350,0),Margin=new Padding(0,0,0,12)});foreach(string id in languageSettings.Favorites){string chosen=id;var button=Button(TranslationCatalog.Find(id).Name,(s,e)=>{replace=chosen;dialog.DialogResult=DialogResult.OK;});button.Width=350;button.Height=34;stack.Controls.Add(button);}var cancelButton=Button("Cancel",(s,e)=>dialog.DialogResult=DialogResult.Cancel);stack.Controls.Add(cancelButton);dialog.CancelButton=cancelButton;ApplyControlTheme(dialog);if(dialog.ShowDialog(owner)!=DialogResult.OK)return;}if(replace==null)return;int position=languageSettings.Favorites.IndexOf(replace);languageSettings.Favorites[position]=item.Id;
        }SaveLanguagePreferences();RebuildQuickLanguages();UpdateTargetActions();}
        void RebuildQuickLanguages(){if(translationLanguageRow==null)return;translationHints.RemoveAll();foreach(Control old in translationLanguageRow.Controls.Cast<Control>().ToArray()){translationLanguageRow.Controls.Remove(old);old.Dispose();}translations.Clear();foreach(var id in languageSettings.Favorites){var item=TranslationCatalog.Find(id);var button=Button(item.ShortName,(s,e)=>SelectTranslationTarget(item));button.Height=32;button.Margin=Padding.Empty;button.Enabled=!busy;button.Tag=item.Id==currentTarget?"selected":"secondary";translationHints.SetToolTip(button,item.Name);translations.Add(button);translationLanguageRow.Controls.Add(button);}moreLanguages=Button("…",async(s,e)=>await ChooseTranslationLanguage());moreLanguages.AccessibleName="More translation languages and favorites";moreLanguages.Width=34;moreLanguages.Height=30;moreLanguages.Margin=Padding.Empty;moreLanguages.Enabled=!busy;translationHints.SetToolTip(moreLanguages,"More languages / manage favorites");translationLanguageRow.Controls.Add(moreLanguages);SizeQuickLanguages();UpdateTranslateAction();ApplyTheme();}
        void SizeQuickLanguages(){if(moreLanguages==null)return;int available=Math.Max(0,translationLanguageRow.ClientSize.Width-moreLanguages.Width-12),width=translations.Count==0?0:Math.Max(1,Math.Min(104,(available-Math.Max(0,translations.Count-1)*6)/translations.Count));int x=0;foreach(var button in translations){button.SetBounds(x,0,width,32);x+=width+6;}moreLanguages.Location=new Point(Math.Max(0,translationLanguageRow.ClientSize.Width-moreLanguages.Width),1);}
        void SelectTranslationTarget(TranslationLanguage item){if(busy||item==null)return;currentTarget=item.Id;UpdateTranslateAction();foreach(var button in translations)button.Tag=languageSettings.Favorites.IndexOf(item.Id)==translations.IndexOf(button)?"selected":"secondary";UpdateTranslationState();ApplyTheme();}
        async Task TranslateTarget(TranslationLanguage item){if(busy||item==null)return;SelectTranslationTarget(item);if(!AiSignedIn||aiWorking)return;await Translate(item.Id,item.Name);}
        async Task ChooseTranslationLanguage(){
            if(busy)return;TranslationLanguage chosen=null;using(var dialog=new Form{Text="Translate to",ClientSize=new Size(520,470),MinimumSize=new Size(500,440),StartPosition=FormStartPosition.CenterParent,ShowInTaskbar=false,MinimizeBox=false,MaximizeBox=false,Icon=Icon,Font=Font}){
                var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,Padding=new Padding(20),Margin=Padding.Empty};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,28));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,52));dialog.Controls.Add(layout);var search=new TextBox{AccessibleName="Search translation language"};var searchFrame=LanguageSearch(search);searchFrame.Dock=DockStyle.Fill;searchFrame.Margin=new Padding(0,0,0,12);layout.Controls.Add(searchFrame,0,0);var list=LanguageList("Translation languages");var listFrame=LanguageListFrame(list);listFrame.Dock=DockStyle.Fill;listFrame.Margin=Padding.Empty;layout.Controls.Add(listFrame,0,1);var info=new Label{Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,Font=new Font("Segoe UI",9),Margin=Padding.Empty};layout.Controls.Add(info,0,2);
                var row=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=1,Padding=new Padding(0,12,0,0),Margin=Padding.Empty};row.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));row.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,82));row.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,8));row.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,96));row.RowStyles.Add(new RowStyle(SizeType.Percent,100));var favorite=Button("Add favorite",(s,e)=>{var item=list.SelectedItem as TranslationLanguage;if(item!=null){ChangeFavorite(item,dialog);list.Invalidate();}});favorite.AccessibleName="Toggle translation favorite";favorite.Width=150;favorite.Dock=DockStyle.Left;favorite.Margin=Padding.Empty;row.Controls.Add(favorite,0,0);var translate=Button("Translate",(s,e)=>{chosen=list.SelectedItem as TranslationLanguage;if(chosen!=null)dialog.DialogResult=DialogResult.OK;},true);translate.Dock=DockStyle.Fill;translate.Margin=Padding.Empty;row.Controls.Add(translate,3,0);var cancelButton=Button("Cancel",(s,e)=>dialog.DialogResult=DialogResult.Cancel);cancelButton.Dock=DockStyle.Fill;cancelButton.Margin=Padding.Empty;row.Controls.Add(cancelButton,1,0);layout.Controls.Add(row,0,3);
                Action selection=()=>{var item=list.SelectedItem as TranslationLanguage;translate.Enabled=AiSignedIn&&!aiWorking&&!String.IsNullOrWhiteSpace(source.Text)&&item!=null;favorite.Enabled=item!=null;favorite.Text=item!=null&&languageSettings.Favorites.Contains(item.Id)?"Remove favorite":"Add favorite";info.Text="Favorites: "+languageSettings.Favorites.Count+"/3";};Action filter=()=>{string keep=(list.SelectedItem as TranslationLanguage)==null?currentTarget:((TranslationLanguage)list.SelectedItem).Id;list.Items.Clear();foreach(var item in TranslationCatalog.Search(search.Text))list.Items.Add(item);if(list.Items.Count>0){int index=list.Items.Cast<TranslationLanguage>().ToList().FindIndex(v=>v.Id==keep);list.SelectedIndex=Math.Max(0,index);}selection();};list.SelectedIndexChanged+=(s,e)=>selection();favorite.Click+=(s,e)=>selection();search.TextChanged+=(s,e)=>filter();filter();dialog.AcceptButton=translate;dialog.CancelButton=cancelButton;ApplyControlTheme(dialog);if(dialog.ShowDialog(this)!=DialogResult.OK)return;
            }if(chosen!=null)await TranslateTarget(chosen);
        }
    }
